-- Generated by Claude Code — Konto in der App löschen (App-Store-Pflicht,
-- Richtlinie 5.1.1(v)). Löscht den eigenen Auth-Account samt aller
-- personenbezogenen Daten. Verweise ohne "on delete cascade" werden vorher
-- aufgelöst: nullable Spalten (z. B. reviewed_by, created_by) auf NULL,
-- sonstige Zeilen (z. B. event_views) gelöscht. Konten mit ausgestellten
-- Rechnungen bleiben bestehen (gesetzliche Aufbewahrungspflicht).
create or replace function delete_my_account()
returns void
language plpgsql
security definer
set search_path = public
as $$
declare
  v_uid uuid := auth.uid();
  fk record;
begin
  if v_uid is null then raise exception 'Nicht angemeldet.'; end if;

  if exists (
    select 1 from promotion_invoices i
    join event_promotions p on p.id = i.promotion_id
    where p.requested_by = v_uid
  ) then
    raise exception 'Dieses Konto hat Rechnungen, die wir gesetzlich aufbewahren müssen. Bitte schreib uns an jakob@klangradar.com, wir löschen alle übrigen Daten.';
  end if;

  for fk in
    select c.conrelid::regclass as tbl, a.attname as col, a.attnotnull as notnull
    from pg_constraint c
    join pg_attribute a on a.attrelid = c.conrelid and a.attnum = c.conkey[1]
    where c.contype = 'f'
      and c.confrelid in ('public.profiles'::regclass, 'auth.users'::regclass)
      and c.confdeltype in ('a', 'r')
      and array_length(c.conkey, 1) = 1
  loop
    if fk.notnull then
      execute format('delete from %s where %I = $1', fk.tbl, fk.col) using v_uid;
    else
      execute format('update %s set %I = null where %I = $1', fk.tbl, fk.col, fk.col) using v_uid;
    end if;
  end loop;

  delete from auth.users where id = v_uid;
end;
$$;

revoke all on function delete_my_account() from public, anon;
grant execute on function delete_my_account() to authenticated;
